package com.mycompany.projetmedical.dao;

import com.mycompany.projetmedical.util.Bdd;
import com.mycompany.projetmedical.util.Journal;
import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDate;
import java.time.LocalTime;
import java.util.*;

/** Accès au portail personnel, chaque requête est bornée par l'identifiant du compte connecté. */
public class PatientPortailDao {
    public record Profil(int id,String numero,String nom,String prenoms,String email,String telephone,String adresse,String sexe,LocalDate naissance,String profession,String contactUrgence,String telephoneUrgence,String groupeSanguin,String rattachement){}
    public record Dossier(String antecedentsGeneraux,String allergies,String traitements,String notes,Timestamp ouverture){}
    public record Stats(String numero,long prochainsRdv,long consultations,long facturesOuvertes,BigDecimal solde,int notifications){}
    public record Rdv(long id,LocalDate date,LocalTime debut,LocalTime fin,String medecin,String service,String motif,String statut){}
    public record Medecin(long id,String nom,String service){}
    public record Consultation(long id,Timestamp date,String medecin,String motif,String observations,String diagnostic,String conduite,String statut){}
    public record Antecedent(String type,String libelle,String description,LocalDate debut){}
    public record Prescription(long id,Timestamp date,String medecin,String statut,String notes,String medicament,String dosage,String posologie,String duree,String quantite,String instructions){}
    public record Analyse(String type,Timestamp date,String valeur,String unite,String references,String observations){}
    public record Facture(long id,String numero,LocalDate date,LocalDate echeance,String statut,BigDecimal total,BigDecimal paye,BigDecimal restant,String notes,List<Ligne> lignes){}
    public record Ligne(String libelle,BigDecimal quantite,BigDecimal prix,BigDecimal montant){}
    public record Paiement(long id,long factureId,String numeroFacture,BigDecimal montant,String mode,Timestamp date,String reference,String notes,BigDecimal solde){}
    public record Notification(long id,String titre,String message,String type,String lien,boolean lue,Timestamp date){}

    public Profil profil(int patient)throws SQLException{
        String q="SELECT p.utilisateur_id,p.numero_dossier,u.nom,u.prenoms,u.email,u.telephone,u.adresse,u.sexe,u.date_naissance,p.profession,p.contact_urgence,p.telephone_urgence,p.groupe_sanguin,p.rattachement_statut FROM patients p JOIN utilisateurs u ON u.id=p.utilisateur_id WHERE p.utilisateur_id=? AND u.role_code='PATIENT'";
        try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){if(!r.next())return null;java.sql.Date d=r.getDate("date_naissance");return new Profil(r.getInt(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),d==null?null:d.toLocalDate(),r.getString(10),r.getString(11),r.getString(12),r.getString(13),r.getString(14));}}
    }
    public Stats stats(int patient)throws SQLException{
        String q="SELECT p.numero_dossier,(SELECT count(*) FROM rendez_vous WHERE patient_id=? AND date_rdv>=CURRENT_DATE AND statut IN ('EN_ATTENTE','CONFIRME')),(SELECT count(*) FROM consultations WHERE patient_id=?),(SELECT count(*) FROM factures WHERE patient_id=? AND statut IN ('EN_ATTENTE','PARTIELLEMENT_PAYEE')),(SELECT coalesce(sum(montant_restant),0) FROM factures WHERE patient_id=? AND statut IN ('EN_ATTENTE','PARTIELLEMENT_PAYEE')),(SELECT count(*) FROM notifications WHERE utilisateur_id=? AND lue=false) FROM patients p WHERE p.utilisateur_id=?";
        try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement(q)){for(int i=1;i<=5;i++)s.setInt(i,patient);s.setInt(6,patient);try(ResultSet r=s.executeQuery()){if(!r.next())return null;return new Stats(r.getString(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getBigDecimal(5),r.getInt(6));}}
    }
    public Dossier dossier(int patient)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement("SELECT antecedents_generaux,allergies,traitements_en_cours,notes_administratives,date_ouverture FROM dossiers_medicaux WHERE patient_id=?")){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){return r.next()?new Dossier(r.getString(1),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5)):null;}}}
    public List<Antecedent> antecedents(int patient)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement("SELECT type,libelle,description,date_debut FROM antecedents_medicaux WHERE patient_id=? ORDER BY date_enregistrement DESC")){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){List<Antecedent>a=new ArrayList<>();while(r.next()){java.sql.Date d=r.getDate(4);a.add(new Antecedent(r.getString(1),r.getString(2),r.getString(3),d==null?null:d.toLocalDate()));}return a;}}}
    public List<Consultation> consultations(int patient)throws SQLException{String q="SELECT c.id,c.date_consultation,coalesce(m.prenoms||' '||m.nom,''),c.motif,c.observations,c.diagnostic,c.conduite_a_tenir,c.statut FROM consultations c LEFT JOIN utilisateurs m ON m.id=c.medecin_id WHERE c.patient_id=? AND c.statut='TERMINEE' ORDER BY c.date_consultation DESC LIMIT 200";try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){List<Consultation>a=new ArrayList<>();while(r.next())a.add(new Consultation(r.getLong(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8)));return a;}}}
    public List<Prescription> prescriptions(int patient)throws SQLException{String q="SELECT pr.id,pr.date_prescription,coalesce(m.prenoms||' '||m.nom,''),pr.statut,pr.notes,pd.medicament,pd.dosage,pd.posologie,pd.duree,pd.quantite,pd.instructions FROM prescriptions pr LEFT JOIN utilisateurs m ON m.id=pr.medecin_id LEFT JOIN prescription_details pd ON pd.prescription_id=pr.id WHERE pr.patient_id=? ORDER BY pr.date_prescription DESC,pd.id LIMIT 500";try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){List<Prescription>a=new ArrayList<>();while(r.next())a.add(new Prescription(r.getLong(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getString(11)));return a;}}}
    public List<Analyse> analysesValidees(int patient)throws SQLException{String q="SELECT t.libelle,r.date_validation,r.valeur,r.unite,r.valeurs_reference,r.observations FROM demandes_analyses d JOIN types_analyses t ON t.id=d.type_analyse_id JOIN resultats_analyses r ON r.demande_id=d.id WHERE d.patient_id=? AND r.statut='VALIDE' AND r.date_validation IS NOT NULL ORDER BY r.date_validation DESC";try(Connection c=Bdd.connexion();PreparedStatement s=c.prepareStatement(q)){s.setInt(1,patient);try(ResultSet r=s.executeQuery()){List<Analyse>a=new ArrayList<>();while(r.next())a.add(new Analyse(r.getString(1),r.getTimestamp(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6)));return a;}}}
    public List<Medecin> medecins()throws SQLException{String q="SELECT u.id,u.prenoms||' '||u.nom,s.nom FROM utilisateurs u LEFT JOIN services s ON s.id=u.service_id WHERE u.role_code='MEDECIN' AND u.statut='ACTIF' ORDER BY u.nom,u.prenoms";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){List<Medecin>a=new ArrayList<>();while(r.next())a.add(new Medecin(r.getLong(1),r.getString(2),r.getString(3)));return a;}}
    public List<Rdv> rendezVous(int patient)throws SQLException{String q="SELECT r.id,r.date_rdv,r.heure_debut,r.heure_fin,coalesce(u.prenoms||' '||u.nom,''),s.nom,r.motif,r.statut FROM rendez_vous r JOIN utilisateurs u ON u.id=r.medecin_id LEFT JOIN services s ON s.id=r.service_id WHERE r.patient_id=? ORDER BY r.date_rdv DESC,r.heure_debut DESC LIMIT 300";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);try(ResultSet r=p.executeQuery()){List<Rdv>a=new ArrayList<>();while(r.next())a.add(new Rdv(r.getLong(1),r.getDate(2).toLocalDate(),r.getTime(3).toLocalTime(),r.getTime(4).toLocalTime(),r.getString(5),r.getString(6),r.getString(7),r.getString(8)));return a;}}}
    public void demanderRendezVous(int patient,long medecin,LocalDate date,LocalTime debut,LocalTime fin,String motif,String ip)throws SQLException{
        if(date.isBefore(LocalDate.now())||!fin.isAfter(debut))throw new IllegalArgumentException("Choisissez une date à venir et une heure de fin après le début.");
        try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{
            String conflict="SELECT count(*) FROM rendez_vous WHERE statut<>'ANNULE' AND date_rdv=? AND (medecin_id=? OR patient_id=?) AND heure_debut<? AND heure_fin>?";try(PreparedStatement p=c.prepareStatement(conflict)){p.setDate(1,java.sql.Date.valueOf(date));p.setLong(2,medecin);p.setInt(3,patient);p.setTime(4,Time.valueOf(fin));p.setTime(5,Time.valueOf(debut));try(ResultSet r=p.executeQuery()){r.next();if(r.getLong(1)>0)throw new SQLException("Ce créneau est déjà occupé pour le médecin ou votre compte.","23P01");}}
            String q="INSERT INTO rendez_vous(patient_id,medecin_id,service_id,date_rdv,heure_debut,heure_fin,motif,statut,cree_par) SELECT ?,u.id,u.service_id,?,?,?,?,'EN_ATTENTE',? FROM utilisateurs u JOIN patients p ON p.utilisateur_id=? WHERE u.id=? AND u.role_code='MEDECIN' AND u.statut='ACTIF'";
            long id;try(PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,patient);p.setDate(2,java.sql.Date.valueOf(date));p.setTime(3,Time.valueOf(debut));p.setTime(4,Time.valueOf(fin));p.setString(5,motif);p.setInt(6,patient);p.setInt(7,patient);p.setLong(8,medecin);if(p.executeUpdate()!=1)throw new SQLException("Médecin ou patient indisponible.","02000");try(ResultSet r=p.getGeneratedKeys()){if(!r.next())throw new SQLException("Impossible de lire le rendez-vous créé.");id=r.getLong(1);}}
            Journal.ecrire(c,(long)patient,Journal.CREATION_RDV,"rendez_vous",id,"Demande de rendez-vous créée par le patient",true,ip);c.commit();
        }catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    public void annulerRendezVous(int patient,long rdv,String ip)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("UPDATE rendez_vous SET statut='ANNULE',annule_par=?,motif_annulation='Annulation demandée par le patient',date_modification=now() WHERE id=? AND patient_id=? AND statut IN ('EN_ATTENTE','CONFIRME') AND date_rdv>=CURRENT_DATE")){p.setInt(1,patient);p.setLong(2,rdv);p.setInt(3,patient);if(p.executeUpdate()!=1)throw new SQLException("Ce rendez-vous ne peut plus être annulé depuis votre espace.","42501");Journal.ecrire((long)patient,Journal.ANNULATION_RDV,"rendez_vous",rdv,"Annulation demandée par le patient",true,ip);}}
    public void modifierProfil(int patient,String nom,String prenoms,String email,String telephone,String adresse,String urgence,String telUrgence,String ip)throws SQLException{
        try(Connection c=Bdd.connexion()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("UPDATE utilisateurs SET nom=?,prenoms=?,email=?,telephone=?,adresse=?,date_modification=now() WHERE id=? AND role_code='PATIENT'")){p.setString(1,nom);p.setString(2,prenoms);p.setString(3,email);p.setString(4,telephone);p.setString(5,adresse);p.setInt(6,patient);if(p.executeUpdate()!=1)throw new SQLException("Compte patient introuvable.","02000");}try(PreparedStatement p=c.prepareStatement("UPDATE patients SET contact_urgence=?,telephone_urgence=? WHERE utilisateur_id=?")){p.setString(1,urgence);p.setString(2,telUrgence);p.setInt(3,patient);p.executeUpdate();}Journal.ecrire(c,(long)patient,Journal.MODIFICATION_COMPTE,"utilisateurs",(long)patient,"Mise à jour des coordonnées personnelles",true,ip);c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    public List<Facture> factures(int patient)throws SQLException{String q="SELECT id,numero_facture,date_facture,echeance,statut,montant_total,montant_paye,montant_restant,notes FROM factures WHERE patient_id=? ORDER BY date_facture DESC,id DESC LIMIT 300";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);try(ResultSet r=p.executeQuery()){List<Facture>a=new ArrayList<>();while(r.next()){java.sql.Date e=r.getDate(4);a.add(new Facture(r.getLong(1),r.getString(2),r.getDate(3).toLocalDate(),e==null?null:e.toLocalDate(),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getString(9),List.of()));}return a;}}}
    public Facture facture(int patient,long id)throws SQLException{String q="SELECT id,numero_facture,date_facture,echeance,statut,montant_total,montant_paye,montant_restant,notes FROM factures WHERE patient_id=? AND id=?";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);p.setLong(2,id);try(ResultSet r=p.executeQuery()){if(!r.next())return null;java.sql.Date e=r.getDate(4);return new Facture(r.getLong(1),r.getString(2),r.getDate(3).toLocalDate(),e==null?null:e.toLocalDate(),r.getString(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getString(9),lignes(patient,id));}}}
    private List<Ligne> lignes(int patient,long facture)throws SQLException{String q="SELECT l.libelle,l.quantite,l.prix_unitaire,l.montant_ligne FROM lignes_facture l JOIN factures f ON f.id=l.facture_id WHERE f.patient_id=? AND f.id=? ORDER BY l.id";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);p.setLong(2,facture);try(ResultSet r=p.executeQuery()){List<Ligne>a=new ArrayList<>();while(r.next())a.add(new Ligne(r.getString(1),r.getBigDecimal(2),r.getBigDecimal(3),r.getBigDecimal(4)));return a;}}}
    public List<Paiement> paiements(int patient)throws SQLException{String q="SELECT p.id,p.facture_id,f.numero_facture,p.montant,p.mode_paiement,p.date_paiement,p.reference,p.notes,f.montant_total-(SELECT coalesce(sum(p2.montant),0) FROM paiements p2 WHERE p2.facture_id=f.id AND (p2.date_paiement<p.date_paiement OR (p2.date_paiement=p.date_paiement AND p2.id<=p.id))) solde FROM paiements p JOIN factures f ON f.id=p.facture_id WHERE f.patient_id=? ORDER BY p.date_paiement DESC LIMIT 500";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);try(ResultSet r=p.executeQuery()){List<Paiement>a=new ArrayList<>();while(r.next())a.add(new Paiement(r.getLong(1),r.getLong(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getTimestamp(6),r.getString(7),r.getString(8),r.getBigDecimal(9)));return a;}}}
    public Paiement paiement(int patient,long id)throws SQLException{String q="SELECT p.id,p.facture_id,f.numero_facture,p.montant,p.mode_paiement,p.date_paiement,p.reference,p.notes,f.montant_total-(SELECT coalesce(sum(p2.montant),0) FROM paiements p2 WHERE p2.facture_id=f.id AND (p2.date_paiement<p.date_paiement OR (p2.date_paiement=p.date_paiement AND p2.id<=p.id))) solde FROM paiements p JOIN factures f ON f.id=p.facture_id WHERE f.patient_id=? AND p.id=?";try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,patient);p.setLong(2,id);try(ResultSet r=p.executeQuery()){return r.next()?new Paiement(r.getLong(1),r.getLong(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getTimestamp(6),r.getString(7),r.getString(8),r.getBigDecimal(9)):null;}}}
    public List<Notification> notifications(int patient)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("SELECT id,titre,message,type,lien,lue,date_creation FROM notifications WHERE utilisateur_id=? ORDER BY date_creation DESC LIMIT 200")){p.setInt(1,patient);try(ResultSet r=p.executeQuery()){List<Notification>a=new ArrayList<>();while(r.next())a.add(new Notification(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getBoolean(6),r.getTimestamp(7)));return a;}}}
    public void lireNotification(int patient,long id)throws SQLException{try(Connection c=Bdd.connexion();PreparedStatement p=c.prepareStatement("UPDATE notifications SET lue=true WHERE utilisateur_id=? AND id=?")){p.setInt(1,patient);p.setLong(2,id);p.executeUpdate();}}
}
